A tiny, illustrative HNSW-style search, using plain dicts to stand in for the graph:

```python
# A tiny, illustrative HNSW-style search (NOT production code).
# Two layers: layer1 is sparse/long-range, layer0 is dense/local.

graph = {
    "layer1": {
        "A": ["D"],
        "D": ["A", "H"],
        "H": ["D"],
    },
    "layer0": {
        "A": ["B", "D"],
        "B": ["A", "C"],
        "C": ["B", "D"],
        "D": ["A", "C", "E", "H"],
        "E": ["D", "F"],
        "F": ["E", "G"],
        "G": ["F", "H"],
        "H": ["D", "G"],
    },
}

positions = {"A": 0, "B": 1, "C": 2, "D": 3, "E": 4, "F": 5, "G": 6, "H": 7}


def distance(node, query):
    return abs(positions[node] - query)


def greedy_search(layer, start, query, ef=1):
    """Explore up to `ef` candidates, always stepping to the closest one found."""
    current = start
    visited = {current}
    improved = True
    while improved:
        improved = False
        candidates = sorted(graph[layer][current], key=lambda n: distance(n, query))[:ef]
        for neighbor in candidates:
            if neighbor not in visited and distance(neighbor, query) < distance(current, query):
                current = neighbor
                improved = True
        visited.add(current)
    return current


def hnsw_search(query, ef=1):
    entry = greedy_search("layer1", "A", query, ef=ef)
    return greedy_search("layer0", entry, query, ef=ef)


print(hnsw_search(query=6, ef=1))  # descends layer1, then refines within layer0
```

`hnsw_search` always enters through the fixed node `"A"` on the sparse `layer1`, uses it to jump toward the right neighborhood, and only then switches to the denser `layer0` graph to refine the answer step by step. Notice that raising `ef` simply widens how many neighbors `greedy_search` is allowed to compare at each step before committing to a move.

A tiny 1-D-style simulation of IVF cluster assignment plus a very simplified product-quantization step:

```python
import math

# A tiny IVF + product-quantization simulation (NOT production code).

vectors = {
    "v1": [0.0, 0.1],
    "v2": [0.05, 0.0],
    "v3": [5.0, 5.1],
    "v4": [5.2, 4.9],
    "v5": [10.0, 10.2],
    "v6": [9.8, 10.1],
}

centroids = {
    "c0": [0.0, 0.0],
    "c1": [5.0, 5.0],
    "c2": [10.0, 10.0],
}


def euclidean(a, b):
    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))


def assign_to_cluster(vector, centroids):
    return min(centroids, key=lambda c: euclidean(vector, centroids[c]))


inverted_lists = {c: [] for c in centroids}
for name, vec in vectors.items():
    cluster = assign_to_cluster(vec, centroids)
    inverted_lists[cluster].append(name)


def pq_code(vector, codebook):
    # Represent the vector by the id of its closest codebook entry.
    return min(codebook, key=lambda code: euclidean(vector, codebook[code]))


codebook = {0: [0.0, 0.0], 1: [5.0, 5.0], 2: [10.0, 10.0]}
compressed = {name: pq_code(vec, codebook) for name, vec in vectors.items()}


def ivf_search(query, nprobe=1):
    ranked_clusters = sorted(centroids, key=lambda c: euclidean(query, centroids[c]))[:nprobe]
    candidates = [v for c in ranked_clusters for v in inverted_lists[c]]
    return candidates


print(inverted_lists)                     # which vectors landed in each cluster
print(compressed)                         # each vector replaced by one small integer code
print(ivf_search([9.5, 9.9], nprobe=1))   # only searches the nearest cluster's members
```

`assign_to_cluster` is the IVF step: it buckets every vector under its nearest centroid, and `ivf_search` only ever looks inside the `nprobe` closest buckets. `pq_code` is a stand-in for product quantization: it throws away the original coordinates and keeps only a tiny integer id, which is exactly the kind of compression that makes IVF-PQ so memory-efficient at scale.
